package com.vit.archds.entity; import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="explanations") public class Explanation { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="candidate_id") private ArchitectureCandidate candidate; @Lob private String rationale; @Lob private String strengthsJson; @Lob private String tradeoffsJson; @Lob private String risksJson; @Lob private String assumptionsJson; private Double confidence; @Lob private String changeFactorsJson; @Column(nullable=false) private Instant createdAt=Instant.now(); public Explanation(){} public Explanation(ArchitectureCandidate c,String r,String s,String t,String ri,String a,Double conf,String cf){candidate=c;rationale=r;strengthsJson=s;tradeoffsJson=t;risksJson=ri;assumptionsJson=a;confidence=conf;changeFactorsJson=cf;} }
